package dk.stream.android;
import java.util.*;
final class ExternalPlaybackType {
 static String mime(String uri,String fallback){return mime(uri,"",fallback);}
 static String mime(String uri,String name,String fallback){String path=uri==null?"":uri.split("[?#]",2)[0];String type=extension(path,fallback);if(type==null)type=extension(name==null?"":name,fallback);return type!=null?type:fallback==null||fallback.isEmpty()||fallback.equals("application/octet-stream")?"video/*":fallback;}
 private static String extension(String value,String fallback){String path=value.toLowerCase(Locale.ROOT);if(path.endsWith(".m3u8"))return "application/vnd.apple.mpegurl";if(path.endsWith(".mpd"))return "application/dash+xml";if(path.endsWith(".mp3"))return "audio/mpeg";if(path.endsWith(".m4a")||path.endsWith(".m4b"))return "audio/mp4";if(path.endsWith(".aac"))return "audio/aac";if(path.endsWith(".flac"))return "audio/flac";if(path.endsWith(".wav"))return "audio/wav";if(path.endsWith(".ogg")||path.endsWith(".oga")||path.endsWith(".opus"))return "audio/ogg";if(path.endsWith(".amr"))return "audio/amr";if(path.endsWith(".aif")||path.endsWith(".aiff"))return "audio/aiff";if(path.endsWith(".wma"))return "audio/x-ms-wma";if(path.endsWith(".mp4")||path.endsWith(".m4v"))return fallback!=null&&fallback.startsWith("audio/")?"audio/mp4":"video/mp4";if(path.endsWith(".mkv"))return "video/x-matroska";if(path.endsWith(".webm"))return "video/webm";if(path.endsWith(".ts"))return "video/mp2t";if(path.endsWith(".mov"))return "video/quicktime";if(path.endsWith(".avi"))return "video/x-msvideo";if(path.endsWith(".mpg")||path.endsWith(".mpeg"))return "video/mpeg";if(path.endsWith(".3gp"))return "video/3gpp";return null;}
 static List<String> candidates(String mime,String family){LinkedHashSet<String> types=new LinkedHashSet<>();types.add(mime);if(mime.toLowerCase(Locale.ROOT).contains("mpegurl")){types.add("application/x-mpegURL");if("audio".equals(family))types.add("audio/x-mpegurl");}types.add((mime.startsWith("audio/")?"audio":"audio".equals(family)?"audio":"video")+"/*");return new ArrayList<>(types);}
 private ExternalPlaybackType(){}
}
